#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_transpose_v2.h"
#include <torch/extension.h>

namespace ascend_kernel {

/*
 * Tiling 参数结构体
 * 通过 workspace 传递给 kernel
 */
struct TransposeV2Tiling {
    int64_t totalElements;     // 输出总元素数
    int64_t dimASize;          // 互换维 A 的大小
    int64_t dimBSize;          // 互换维 B 的大小
    int64_t blockSize;         // 连续内层维度的元素乘积 (数据搬移粒度)
    int64_t tileSize;          // UB 内分块转置的方块边长 (以 block 为单位)
    int64_t startBatch;        // 本 core 的第一个 batch 索引
    int64_t numBatches;        // 本 core 处理的 batch 数量
    int64_t ndim;              // 张量维度数 (3 或 4)
    int64_t inputShape[4];     // 输入 shape
    int64_t outputShape[4];    // 输出 shape
    int64_t inputStrides[4];   // 输入每个维度的 stride (元素数)
    int64_t outputStrides[4];  // 输出每个维度的 stride (元素数)
    int64_t batchStrideIn;     // 相邻 batch 在输入中的偏移 (元素数)
    int64_t batchStrideOut;    // 相邻 batch 在输出中的偏移 (元素数)
    int64_t dimAInputStride;   // dimA 在输入中的 stride (元素数)
    int64_t dimBInputStride;   // dimB 在输入中的 stride (元素数)
    int64_t dimAOutputStride;  // dimA 在输出中的 stride (元素数)
    int64_t dimBOutputStride;  // dimB 在输出中的 stride (元素数)
};

// 根据 perm 找到被互换的两个维度 (dimA, dimB)
// 其中 dimA 是在输入中更靠外的维度
static void findSwappedDims(at::IntArrayRef perm,
                             int64_t &dimA, int64_t &dimB) {
    int64_t ndim = static_cast<int64_t>(perm.size());
    dimA = -1;
    dimB = -1;
    for (int64_t i = 0; i < ndim; ++i) {
        if (perm[i] != i) {
            if (dimA < 0) {
                dimA = i;
                dimB = perm[i];
            } else if (i == dimB && perm[i] == dimA) {
                // 确认互换关系
                break;
            }
        }
    }
    // 保证 dimA < dimB (在 perm 中的输入位置)
    if (dimA > dimB) {
        std::swap(dimA, dimB);
    }
}

at::Tensor transpose_v2(const at::Tensor &self,
                         at::IntArrayRef perm) {
    // ---- 输入校验 ----
    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
                "transpose_v2: input must be on NPU device");
    TORCH_CHECK(self.scalar_type() == at::kFloat ||
                self.scalar_type() == at::kHalf,
                "transpose_v2: only float32 and float16 are supported");
    TORCH_CHECK(self.dim() >= 3 && self.dim() <= 4,
                "transpose_v2: only 3D and 4D tensors are supported");

    int64_t ndim = self.dim();
    int64_t dtypeSize = static_cast<int64_t>(self.element_size());

    // ---- 确保输入 contiguous ----
    at::Tensor selfContiguous = self.contiguous();

    // ---- 计算输出 shape ----
    std::vector<int64_t> outputShapeVec;
    for (int64_t i = 0; i < ndim; ++i) {
        outputShapeVec.push_back(selfContiguous.size(perm[i]));
    }
    auto output = at::empty(outputShapeVec,
        selfContiguous.options().dtype(selfContiguous.scalar_type()));

    // ---- 找到被互换的二维 ----
    int64_t dimA = -1, dimB = -1;
    findSwappedDims(perm, dimA, dimB);
    TORCH_CHECK(dimA >= 0 && dimB >= 0,
                "transpose_v2: cannot find swapped dimensions");

    // dimA/dimB 是输入中互换两维的输入索引
    // dimAOut/dimBOut 是这两维在输出中的位置
    int64_t dimAOut = -1, dimBOut = -1;
    for (int64_t i = 0; i < ndim; ++i) {
        if (perm[i] == dimA) dimAOut = i;
        if (perm[i] == dimB) dimBOut = i;
    }

    int64_t dimASize = selfContiguous.size(dimA);
    int64_t dimBSize = selfContiguous.size(dimB);

    // ---- 计算 blockSize (内层连续维度大小) ----
    // blockSize = 所有比 dimA 和 dimB 更"内层"的维度的乘积
    // 这些维度在数据搬移时保持连续，作为搬移的基本单位
    int64_t blockSize = 1;
    int64_t minDim = (dimA < dimB) ? dimA : dimB;
    int64_t maxDim = (dimA > dimB) ? dimA : dimB;
    for (int64_t d = maxDim + 1; d < ndim; ++d) {
        blockSize *= selfContiguous.size(d);
    }
    // 如果互换维包含最内层维度，内层连续元素可能跨散
    // 此时 blockSize 为 1 (逐元素搬移)
    int64_t innermostInSwapped = (maxDim == ndim - 1);
    if (innermostInSwapped) {
        blockSize = 1;
    }

    // ---- 计算输入/输出的 strides ----
    std::vector<int64_t> inputShapeV(selfContiguous.sizes().begin(),
                                      selfContiguous.sizes().end());
    std::vector<int64_t> inputStridesV(inputShapeV.size(), 1);
    std::vector<int64_t> outputStridesV(outputShapeVec.size(), 1);
    for (int64_t i = static_cast<int64_t>(inputShapeV.size()) - 2; i >= 0; --i) {
        inputStridesV[i] = inputStridesV[i + 1] * inputShapeV[i + 1];
    }
    for (int64_t i = static_cast<int64_t>(outputShapeVec.size()) - 2; i >= 0; --i) {
        outputStridesV[i] = outputStridesV[i + 1] * outputShapeVec[i + 1];
    }

    // ---- 计算 bundle 级别的参数 ----
    // 将 (dimA, dimB) 互换当做在 (dimA, dimB) 平面上的 2D 转置
    // 每"行"大小为 dimBSize * blockSize，共 dimASize 行
    // "batch" 数 = 除 dimA, dimB 外所有维度的乘积
    int64_t batchCount = 1;
    for (int64_t d = 0; d < ndim; ++d) {
        if (d != dimA && d != dimB) {
            batchCount *= selfContiguous.size(d);
        }
    }

    // ---- 计算 batch 间 stride ----
    // batch 按输入的最外层→最内层顺序编号
    // 对于固定 dimA, dimB 值外的 batch 坐标，其在输入/输出中的偏移需要分别计算
    // 简化：按元素总数切分 batch，每个 batch 内部的 (dimA,dimB) 矩阵在输入中是连续的

    // ---- 获取平台信息 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // ---- UB 级 tiling: 计算 tileSize ----
    // UB 中需要两个队列，每个队列 double buffer
    // inQueue: 2 * tileElements (tileSize * tileSize * blockSize) 个元素
    // outQueue: 2 * tileElements 个元素
    // 总计: 4 * tileSize^2 * blockSize * dtypeSize bytes <= ubSize
    int64_t maxTileElems = static_cast<int64_t>(ubSize) / (4 * dtypeSize * blockSize);
    int64_t tileSize = static_cast<int64_t>(std::sqrt(static_cast<double>(maxTileElems)));
    // 限制 tileSize 范围，避免过大或过小
    if (tileSize < 1) tileSize = 1;
    if (tileSize > 64) tileSize = 64;
    // 32 字节对齐 (以 block 为单位)
    int64_t ubAlignElems = 32 / static_cast<int64_t>(sizeof(float));  // 以 float 为基础对齐
    if (blockSize > 1) ubAlignElems = 1;  // block 粒度搬移，block 本身保证对齐
    if (tileSize < ubAlignElems && ubAlignElems > 1) tileSize = ubAlignElems;
    if (tileSize > 64) tileSize = 64;

    int64_t tileElements = tileSize * tileSize * blockSize;

    // ---- Block 级 tiling: 按 batch 切分到各 core ----
    int64_t usedCoreNum = std::min(batchCount, coreNum);
    if (usedCoreNum < 1) usedCoreNum = 1;
    int64_t batchesPerCore = batchCount / usedCoreNum;
    int64_t remainderBatches = batchCount % usedCoreNum;

    // ---- 逐 core 分配 batch range 并 launch ----
    // 每个 core 单独 launch 以确保偏移计算正确
    int64_t currentStartBatch = 0;

    // ---- 计算 batch offset 辅助函数 (host 端) ----
    // 将 batch 线性索引映射到 (dimA, dimB) 外的多维坐标
    // 再计算该坐标在输入/输出中的线性偏移
    auto computeBatchOffsets = [&](int64_t batchIdx,
                                    int64_t &inOffset, int64_t &outOffset) {
        // 将 batchIdx 分解为除 dimA, dimB 外的维度坐标
        std::vector<int64_t> dimCoords(ndim, 0);
        int64_t remaining = batchIdx;
        for (int64_t d = ndim - 1; d >= 0; --d) {
            if (d == dimA || d == dimB) continue;
            int64_t dimSize = selfContiguous.size(d);
            dimCoords[d] = remaining % dimSize;
            remaining /= dimSize;
        }

        // 计算输入中的偏移
        inOffset = 0;
        for (int64_t d = 0; d < ndim; ++d) {
            if (d == dimA || d == dimB) continue;
            inOffset += dimCoords[d] * inputStridesV[d];
        }

        // 计算输出中的偏移 (输出坐标中 dimA→dimBOut, dimB→dimAOut)
        std::vector<int64_t> outCoords(ndim, 0);
        for (int64_t d = 0; d < ndim; ++d) {
            if (d == dimA || d == dimB) continue;
            outCoords[d] = dimCoords[d];
        }
        outOffset = 0;
        for (int64_t d = 0; d < ndim; ++d) {
            if (d == dimAOut || d == dimBOut) continue;
            outOffset += outCoords[d] * outputStridesV[d];
        }
    };

    // ---- 计算各 core 的 batch 范围 ----
    std::vector<int64_t> coreStartBatches(usedCoreNum);
    std::vector<int64_t> coreNumBatches(usedCoreNum);
    for (int64_t c = 0; c < usedCoreNum; ++c) {
        coreStartBatches[c] = currentStartBatch;
        coreNumBatches[c] = batchesPerCore + (c < remainderBatches ? 1 : 0);
        currentStartBatch += coreNumBatches[c];
    }

    // ---- 填充 tiling 数据 (取第一个 core 的参数作为模板) ----
    TransposeV2Tiling tilingData;
    tilingData.totalElements = selfContiguous.numel();
    tilingData.dimASize = dimASize;
    tilingData.dimBSize = dimBSize;
    tilingData.blockSize = blockSize;
    tilingData.tileSize = tileSize;
    tilingData.ndim = ndim;
    for (int64_t i = 0; i < ndim; ++i) {
        tilingData.inputShape[i] = selfContiguous.size(i);
        tilingData.outputShape[i] = output.size(i);
        tilingData.inputStrides[i] = inputStridesV[i];
        tilingData.outputStrides[i] = outputStridesV[i];
    }
    tilingData.dimAInputStride = inputStridesV[dimA];
    tilingData.dimBInputStride = inputStridesV[dimB];
    tilingData.dimAOutputStride = outputStridesV[dimAOut];
    tilingData.dimBOutputStride = outputStridesV[dimBOut];

    // ---- 逐个 core launch ----
    uint32_t blockDim = 1;  // 单核单 batch 范围
    int64_t blockSizeL = blockSize;
    int64_t dimASizeL = dimASize;
    int64_t dimBSizeL = dimBSize;
    int64_t tileSizeL = tileSize;
    int64_t ndimL = ndim;
    int64_t dimAInputStrideL = tilingData.dimAInputStride;
    int64_t dimBInputStrideL = tilingData.dimBInputStride;
    int64_t dimAOutputStrideL = tilingData.dimAOutputStride;
    int64_t dimBOutputStrideL = tilingData.dimBOutputStride;

    int64_t inputShapeL[4] = {};
    int64_t outputShapeL[4] = {};
    int64_t inputStridesL[4] = {};
    int64_t outputStridesL[4] = {};
    for (int64_t i = 0; i < ndim; ++i) {
        inputShapeL[i] = tilingData.inputShape[i];
        outputShapeL[i] = tilingData.outputShape[i];
        inputStridesL[i] = tilingData.inputStrides[i];
        outputStridesL[i] = tilingData.outputStrides[i];
    }

    for (int64_t c = 0; c < usedCoreNum; ++c) {
        int64_t startBatch = coreStartBatches[c];
        int64_t numBatches = coreNumBatches[c];
        if (numBatches <= 0) continue;

        // 计算该 core 第一个 batch 的输入/输出偏移
        int64_t batchInputBase = 0, batchOutputBase = 0;
        computeBatchOffsets(startBatch, batchInputBase, batchOutputBase);

        int64_t batchStrideIn = 0, batchStrideOut = 0;
        if (numBatches > 1) {
            int64_t nextIn, nextOut;
            computeBatchOffsets(startBatch + 1, nextIn, nextOut);
            batchStrideIn = nextIn - batchInputBase;
            batchStrideOut = nextOut - batchOutputBase;
        }

        EXEC_KERNEL_CMD(transpose_v2, blockDim,
            selfContiguous, output,
            blockSizeL,
            dimASizeL, dimBSizeL,
            tileSizeL,
            startBatch, numBatches,
            ndimL,
            inputShapeL[0], inputShapeL[1], inputShapeL[2], inputShapeL[3],
            outputShapeL[0], outputShapeL[1], outputShapeL[2], outputShapeL[3],
            inputStridesL[0], inputStridesL[1], inputStridesL[2], inputStridesL[3],
            outputStridesL[0], outputStridesL[1], outputStridesL[2], outputStridesL[3],
            dimAInputStrideL, dimBInputStrideL,
            dimAOutputStrideL, dimBOutputStrideL,
            batchInputBase, batchOutputBase,
            batchStrideIn, batchStrideOut,
            dtypeSize
        );
    }

    return output;
}

