#include "kernel_operator.h"

using namespace AscendC;

/*
 * TransposeV2 Kernel
 *
 * 算子语义: x.permute(*self._perm).contiguous()
 * 实现方法: 分块 2D 转置
 *
 * 将 perm 对应的互换二维 (dimA, dimB) 视为一个 2D 矩阵，
 * 其余维度视为 batch。对每个 batch 内的 (dimASize, dimBSize)
 * 矩阵做 tiled 2D transpose。
 *
 * blockSize: 内层连续维度的元素数，作为搬移的基本粒度
 *   例: perm=[0,2,1] on (D0,D1,D2) → dimA=1, dimB=2, blockSize=1
 *   例: perm=[1,0,2] on (D0,D1,D2) → dimA=0, dimB=1, blockSize=D2
 */

template<typename T>
class TransposeV2Kernel {
public:
    __aicore__ inline TransposeV2Kernel() {}

    __aicore__ inline void Init(
        GM_ADDR self, GM_ADDR output,
        int64_t blockSize,
        int64_t dimASize, int64_t dimBSize,
        int64_t tileSize,
        int64_t startBatch, int64_t numBatches,
        int64_t ndim,
        int64_t inputShape0, int64_t inputShape1, int64_t inputShape2, int64_t inputShape3,
        int64_t outputShape0, int64_t outputShape1, int64_t outputShape2, int64_t outputShape3,
        int64_t inputStride0, int64_t inputStride1, int64_t inputStride2, int64_t inputStride3,
        int64_t outputStride0, int64_t outputStride1, int64_t outputStride2, int64_t outputStride3,
        int64_t dimAInputStride, int64_t dimBInputStride,
        int64_t dimAOutputStride, int64_t dimBOutputStride,
        int64_t batchInputBase, int64_t batchOutputBase,
        int64_t batchStrideIn, int64_t batchStrideOut,
        int64_t dtypeSize);

    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t curM, int64_t curN,
                                   int64_t inputBase, int64_t alignedInRowElems);
    __aicore__ inline void Compute(int64_t curM, int64_t curN,
                                    int64_t alignedInRowElems, int64_t alignedOutRowElems);
    __aicore__ inline void CopyOut(int64_t curM, int64_t curN,
                                    int64_t outputBase, int64_t alignedOutRowElems);

private:
    TPipe pipe;
    TQue<TPosition::VECIN, 1> inQueue;
    TQue<TPosition::VECOUT, 1> outQueue;
    GlobalTensor<T> selfGm;
    GlobalTensor<T> outputGm;

    int64_t blockSize_;
    int64_t dimASize_;
    int64_t dimBSize_;
    int64_t tileSize_;
    int64_t startBatch_;
    int64_t numBatches_;
    int64_t ndim_;
    int64_t inputShape_[4];
    int64_t outputShape_[4];
    int64_t inputStrides_[4];
    int64_t outputStrides_[4];
    int64_t dimAInputStride_;
    int64_t dimBInputStride_;
    int64_t dimAOutputStride_;
    int64_t dimBOutputStride_;
    int64_t batchInputBase_;
    int64_t batchOutputBase_;
    int64_t batchStrideIn_;
    int64_t batchStrideOut_;
    int64_t dtypeSize_;
    int64_t tileElements_;
    int64_t alignedInUBElems_;
    int64_t alignedOutUBElems_;
    bool useDataCopyTranspose_;  // blockSize * sizeof(T) >= 32 时用 DataCopy
};

// =========================== Init ============================

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::Init(
    GM_ADDR self, GM_ADDR output,
    int64_t blockSize,
    int64_t dimASize, int64_t dimBSize,
    int64_t tileSize,
    int64_t startBatch, int64_t numBatches,
    int64_t ndim,
    int64_t inputShape0, int64_t inputShape1, int64_t inputShape2, int64_t inputShape3,
    int64_t outputShape0, int64_t outputShape1, int64_t outputShape2, int64_t outputShape3,
    int64_t inputStride0, int64_t inputStride1, int64_t inputStride2, int64_t inputStride3,
    int64_t outputStride0, int64_t outputStride1, int64_t outputStride2, int64_t outputStride3,
    int64_t dimAInputStride, int64_t dimBInputStride,
    int64_t dimAOutputStride, int64_t dimBOutputStride,
    int64_t batchInputBase, int64_t batchOutputBase,
    int64_t batchStrideIn, int64_t batchStrideOut,
    int64_t dtypeSize) {

    blockSize_ = blockSize;
    dimASize_ = dimASize;
    dimBSize_ = dimBSize;
    tileSize_ = tileSize;
    startBatch_ = startBatch;
    numBatches_ = numBatches;
    ndim_ = ndim;
    inputShape_[0] = inputShape0; inputShape_[1] = inputShape1;
    inputShape_[2] = inputShape2; inputShape_[3] = inputShape3;
    outputShape_[0] = outputShape0; outputShape_[1] = outputShape1;
    outputShape_[2] = outputShape2; outputShape_[3] = outputShape3;
    inputStrides_[0] = inputStride0; inputStrides_[1] = inputStride1;
    inputStrides_[2] = inputStride2; inputStrides_[3] = inputStride3;
    outputStrides_[0] = outputStride0; outputStrides_[1] = outputStride1;
    outputStrides_[2] = outputStride2; outputStrides_[3] = outputStride3;
    dimAInputStride_ = dimAInputStride;
    dimBInputStride_ = dimBInputStride;
    dimAOutputStride_ = dimAOutputStride;
    dimBOutputStride_ = dimBOutputStride;
    batchInputBase_ = batchInputBase;
    batchOutputBase_ = batchOutputBase;
    batchStrideIn_ = batchStrideIn;
    batchStrideOut_ = batchStrideOut;
    dtypeSize_ = dtypeSize;

    // 设置 GlobalTensor
    int64_t inputTotal = 1;
    int64_t outputTotal = 1;
    for (int64_t i = 0; i < ndim_; ++i) {
        if (i < 4) {
            inputTotal *= inputShape_[i];
            outputTotal *= outputShape_[i];
        }
    }
    selfGm.SetGlobalBuffer((__gm__ T*)self, inputTotal);
    outputGm.SetGlobalBuffer((__gm__ T*)output, outputTotal);

    // 计算 UB 中的 tile 元素数和对齐长度
    tileElements_ = tileSize_ * tileSize_ * blockSize_;

    // 32B 对齐过的每行元素数 (读入方向: curM 行, 每行 curN * blockSize 元素)
    int64_t maxRowElemsIn = tileSize_ * blockSize_;
    int64_t maxRowBytesIn = maxRowElemsIn * static_cast<int64_t>(sizeof(T));
    alignedInUBElems_ = ((maxRowBytesIn + 31) / 32) * (32 / static_cast<int64_t>(sizeof(T)));

    // 32B 对齐过的每行元素数 (写出方向: curN 行, 每行 curM * blockSize 元素)
    int64_t maxRowElemsOut = tileSize_ * blockSize_;
    int64_t maxRowBytesOut = maxRowElemsOut * static_cast<int64_t>(sizeof(T));
    alignedOutUBElems_ = ((maxRowBytesOut + 31) / 32) * (32 / static_cast<int64_t>(sizeof(T)));

    // 判断 blockSize * sizeof(T) 是否 >= 32，决定 UB 转置用 DataCopy 还是 SetValue/GetValue
    useDataCopyTranspose_ = (blockSize_ * static_cast<int64_t>(sizeof(T)) >= 32);

    // InitBuffer: inQueue + outQueue, 各 double buffer
    int64_t bufBytes = tileElements_ * static_cast<int64_t>(sizeof(T));
    pipe.InitBuffer(inQueue, 2, bufBytes);
    pipe.InitBuffer(outQueue, 2, bufBytes);
}

// =========================== CopyIn ============================

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::CopyIn(
    int64_t curM, int64_t curN,
    int64_t inputBase, int64_t alignedInRowElems) {

    LocalTensor<T> inLocal = inQueue.AllocTensor<T>();

    // 读入 curM 行，每行 curN * blockSize 个元素
    // GM 中行间 stride = dimAInputStride_ 元素 = dimAInputStride_ * sizeof(T) 字节
    //   注意: inputBase 已经指向 tile 的起始位置 [batch + da*ts, db*ts]
    //   行 r 的起始偏移: inputBase + r * dimAInputStride_
    // UB 中行间 stride = alignedInRowElems 元素
    int64_t rowBytes = curN * blockSize_ * static_cast<int64_t>(sizeof(T));
    int64_t srcStrideBytes = dimAInputStride_ * static_cast<int64_t>(sizeof(T));
    int64_t dstStrideDB = (alignedInRowElems * static_cast<int64_t>(sizeof(T))) / 32;

    DataCopyExtParams copyParams{
        static_cast<uint16_t>(curM),                    // blockCount
        static_cast<uint32_t>(rowBytes),                // blockLen (bytes)
        static_cast<uint32_t>(srcStrideBytes),          // srcStride (GM, bytes)
        static_cast<uint16_t>(dstStrideDB > 0 ? dstStrideDB : 1),  // dstStride (UB, 32B blocks)
        0
    };
    DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
    DataCopyPad(inLocal, selfGm[inputBase], copyParams, padParams);

    inQueue.EnQue(inLocal);
}

// =========================== Compute ============================

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::Compute(
    int64_t curM, int64_t curN,
    int64_t alignedInRowElems, int64_t alignedOutRowElems) {

    LocalTensor<T> inLocal = inQueue.DeQue<T>();
    LocalTensor<T> outLocal = outQueue.AllocTensor<T>();

    // UB 内 2D 转置:
    //   inLocal[r * alignedInRowElems + c * blockSize_ + b]
    //   → outLocal[c * alignedOutRowElems + r * blockSize_ + b]

    if (useDataCopyTranspose_) {
        // blockSize * sizeof(T) >= 32, 使用 DataCopy 逐块搬移
        for (int64_t r = 0; r < curM; ++r) {
            for (int64_t c = 0; c < curN; ++c) {
                DataCopy(
                    outLocal[c * alignedOutRowElems + r * blockSize_],
                    inLocal[r * alignedInRowElems + c * blockSize_],
                    static_cast<uint32_t>(blockSize_));
            }
        }
    } else {
        // blockSize 较小时，使用 SetValue/GetValue
        for (int64_t r = 0; r < curM; ++r) {
            int64_t inRowBase = r * alignedInRowElems;
            for (int64_t c = 0; c < curN; ++c) {
                int64_t inOff = inRowBase + c * blockSize_;
                int64_t outOff = c * alignedOutRowElems + r * blockSize_;
                for (int64_t b = 0; b < blockSize_; ++b) {
                    outLocal.SetValue(outOff + b, inLocal.GetValue(inOff + b));
                }
            }
        }
    }

    inQueue.FreeTensor(inLocal);
    outQueue.EnQue(outLocal);
}

// =========================== CopyOut ============================

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::CopyOut(
    int64_t curM, int64_t curN,
    int64_t outputBase, int64_t alignedOutRowElems) {

    LocalTensor<T> outLocal = outQueue.DeQue<T>();

    // 写出 curN 行，每行 curM * blockSize 个元素
    // 行 r 在 GM 中的起始: outputBase + r * dimBOutputStride_
    //   (在输出中，transposed "行" 沿 dimBOut, 每行含 dimAOut 元素)
    int64_t rowBytes = curM * blockSize_ * static_cast<int64_t>(sizeof(T));
    int64_t dstStrideBytes = dimAOutputStride_ * static_cast<int64_t>(sizeof(T));
    // srcStride 是 UB 中行间 padding (gap)
    int64_t srcStrideElements = alignedOutRowElems - curM * blockSize_;
    int64_t srcStrideDB = (srcStrideElements > 0)
        ? static_cast<uint16_t>((srcStrideElements * static_cast<int64_t>(sizeof(T))) / 32)
        : static_cast<uint16_t>(0);

    // 处理 dstStride 的特殊情况: 如果 dimAOutputStride_ == blockSize_ (即 dimA 在输出中连续)
    // 且 curM * blockSize < dimASize_ * blockSize，dstStride 应该是 dimASize_ * blockSize * sizeof(T)
    // 简化处理: 对于逐 batch 写，dstStride 直接使用 dimAOutputStride_ * sizeof(T)

    // 但如果 dimAOutputStride_ 和 blockSize_ 相等且 dimAOutputStride_ == 1 (最内层维)
    // 则写出的行是连续的，dstStride 应为 0 (连续写入)
    int64_t actualDstStrideBytes = dstStrideBytes;
    if (dimAOutputStride_ == blockSize_) {
        actualDstStrideBytes = dimAOutputStride_ * static_cast<int64_t>(sizeof(T));
    }

    DataCopyExtParams copyParams{
        static_cast<uint16_t>(curN),                    // blockCount
        static_cast<uint32_t>(rowBytes),                // blockLen (bytes)
        srcStrideDB,                                     // srcStride (UB, 32B blocks, gap)
        static_cast<uint32_t>(actualDstStrideBytes),    // dstStride (GM, bytes)
        0
    };
    DataCopyPad(outputGm[outputBase], outLocal, copyParams);

    outQueue.FreeTensor(outLocal);
}

// =========================== Process ============================

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::Process() {
    int64_t tileSize = tileSize_;

    for (int64_t bi = 0; bi < numBatches_; ++bi) {
        int64_t batchInputOffset = batchInputBase_ + bi * batchStrideIn_;
        int64_t batchOutputOffset = batchOutputBase_ + bi * batchStrideOut_;

        // 分块 2D 转置: 在 (dimASize_, dimBSize_) 平面上用 tileSize × tileSize 分块
        int64_t dimAM = dimASize_;
        int64_t dimBN = dimBSize_;

        int64_t taTiles = (dimAM + tileSize - 1) / tileSize;
        int64_t tbTiles = (dimBN + tileSize - 1) / tileSize;

        for (int64_t ta = 0; ta < taTiles; ++ta) {
            int64_t curM = tileSize;
            if (ta == taTiles - 1) {
                curM = dimAM - ta * tileSize;
            }
            int64_t inputRowOffset = batchInputOffset + ta * tileSize * dimAInputStride_;

            // 计算本 tile 中读入/写出各行的 32B 对齐长度
            int64_t maxRowLenInBytes = tileSize * blockSize_ * static_cast<int64_t>(sizeof(T));
            int64_t alignedInElems = ((maxRowLenInBytes + 31) / 32) * (32 / static_cast<int64_t>(sizeof(T)));

            int64_t maxRowLenOutBytes = tileSize * blockSize_ * static_cast<int64_t>(sizeof(T));
            int64_t alignedOutElems = ((maxRowLenOutBytes + 31) / 32) * (32 / static_cast<int64_t>(sizeof(T)));

            for (int64_t tb = 0; tb < tbTiles; ++tb) {
                int64_t curN = tileSize;
                if (tb == tbTiles - 1) {
                    curN = dimBN - tb * tileSize;
                }

                int64_t tileInputBase = inputRowOffset + tb * tileSize * dimBInputStride_;
                int64_t tileOutputBase = batchOutputOffset
                    + tb * tileSize * dimAOutputStride_   // 输出中 dimB 沿 dimAOut 方向
                    + ta * tileSize * dimBOutputStride_;  // 输出中 dimA 沿 dimBOut 方向

                CopyIn(curM, curN, tileInputBase, alignedInElems);
                Compute(curM, curN, alignedInElems, alignedOutElems);
                CopyOut(curM, curN, tileOutputBase, alignedOutElems);
            }
        }
    }
}

// =========================== Kernel 入口 ============================

extern "C" __global__ __aicore__ void transpose_v2(
    GM_ADDR self, GM_ADDR output,
    int64_t blockSize,
    int64_t dimASize, int64_t dimBSize,
    int64_t tileSize,
    int64_t startBatch, int64_t numBatches,
    int64_t ndim,
    int64_t inputShape0, int64_t inputShape1, int64_t inputShape2, int64_t inputShape3,
    int64_t outputShape0, int64_t outputShape1, int64_t outputShape2, int64_t outputShape3,
    int64_t inputStride0, int64_t inputStride1, int64_t inputStride2, int64_t inputStride3,
    int64_t outputStride0, int64_t outputStride1, int64_t outputStride2, int64_t outputStride3,
    int64_t dimAInputStride, int64_t dimBInputStride,
    int64_t dimAOutputStride, int64_t dimBOutputStride,
    int64_t batchInputBase, int64_t batchOutputBase,
    int64_t batchStrideIn, int64_t batchStrideOut,
    int64_t dtypeSize) {

    if (dtypeSize == 4) {
        TransposeV2Kernel<float> op;
        op.Init(self, output,
                blockSize, dimASize, dimBSize, tileSize,
                startBatch, numBatches, ndim,
                inputShape0, inputShape1, inputShape2, inputShape3,
                outputShape0, outputShape1, outputShape2, outputShape3,
                inputStride0, inputStride1, inputStride2, inputStride3,
                outputStride0, outputStride1, outputStride2, outputStride3,
                dimAInputStride, dimBInputStride,
                dimAOutputStride, dimBOutputStride,
                batchInputBase, batchOutputBase,
                batchStrideIn, batchStrideOut, dtypeSize);
        op.Process();
    } else if (dtypeSize == 2) {
        TransposeV2Kernel<half> op;
        op.Init(self, output,
                blockSize, dimASize, dimBSize, tileSize,
                startBatch, numBatches, ndim,
                inputShape0, inputShape1, inputShape2, inputShape3,
                outputShape0, outputShape1, outputShape2, outputShape3,
                inputStride0, inputStride1, inputStride2, inputStride3,
                outputStride0, outputStride1, outputStride2, outputStride3,
                dimAInputStride, dimBInputStride,
                dimAOutputStride, dimBOutputStride,
                batchInputBase, batchOutputBase,
                batchStrideIn, batchStrideOut, dtypeSize);
        op.Process();
    }
}
