#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_transpose_v2.h"
#include <torch/extension.h>

namespace ascend_kernel {

at::Tensor transpose_v2(const at::Tensor &self,
                         at::IntArrayRef perm) {
    // ---- 输入校验 ----
    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
                "transpose_v2: input must be on NPU device");
    TORCH_CHECK(self.scalar_type() == at::kFloat ||
                self.scalar_type() == at::kHalf,
                "transpose_v2: only float32 and float16 are supported");
    TORCH_CHECK(self.dim() >= 3 && self.dim() <= 4,
                "transpose_v2: only 3D and 4D tensors are supported");

    int64_t ndim = self.dim();
    int64_t dtypeSize = static_cast<int64_t>(self.element_size());

    // ---- 确保输入 contiguous ----
    at::Tensor selfContiguous = self.contiguous();

    // ---- 计算输出 shape ----
    std::vector<int64_t> outputShapeVec;
    for (int64_t i = 0; i < ndim; ++i) {
        outputShapeVec.push_back(selfContiguous.size(perm[i]));
    }
    auto output = at::empty(outputShapeVec,
        selfContiguous.options().dtype(selfContiguous.scalar_type()));

    // ---- 找到被互换的二维 (dimA, dimB, 在输入中的索引) ----
    int64_t dimA = -1, dimB = -1;
    for (int64_t i = 0; i < ndim; ++i) {
        if (perm[i] != static_cast<int64_t>(i)) {  // NOLINT
            dimA = static_cast<int64_t>(i);        // NOLINT
            dimB = perm[i];
            break;
        }
    }
    TORCH_CHECK(dimA >= 0 && dimB >= 0,
                "transpose_v2: cannot find swapped dimensions");

    // 保证 dimA < dimB（输入维度顺序中 dimA 在 dimB 之前）
    if (dimA > dimB) {
        std::swap(dimA, dimB);
    }

    // dimAOut, dimBOut: 互换两维在输出中的位置
    int64_t dimAOut = -1, dimBOut = -1;
    for (int64_t i = 0; i < ndim; ++i) {
        if (perm[i] == dimA) dimAOut = i;
        if (perm[i] == dimB) dimBOut = i;
    }

    int64_t dimASize = selfContiguous.size(dimA);
    int64_t dimBSize = selfContiguous.size(dimB);

    // ---- 计算 blockSize ----
    // blockSize = 所有比 dimA 和 dimB 都更"内层"的维度乘积
    // 这些元素在数据搬移时保持连续，作为矩阵转置的基本粒度
    int64_t maxSwappedDim = (dimA > dimB) ? dimA : dimB;
    int64_t blockSize = 1;
    for (int64_t d = maxSwappedDim + 1; d < ndim; ++d) {
        blockSize *= selfContiguous.size(d);
    }

    // ---- 计算输入/输出 strides ----
    std::vector<int64_t> inputStridesV(ndim, 1);
    std::vector<int64_t> outputStridesV(ndim, 1);
    for (int64_t i = ndim - 2; i >= 0; --i) {
        inputStridesV[i] = inputStridesV[i + 1] * selfContiguous.size(i + 1);
    }
    for (int64_t i = ndim - 2; i >= 0; --i) {
        outputStridesV[i] = outputStridesV[i + 1] * output.size(i + 1);
    }

    // ---- 计算 batch 总数 ----
    int64_t batchCount = 1;
    for (int64_t d = 0; d < ndim; ++d) {
        if (d != dimA && d != dimB) {
            batchCount *= selfContiguous.size(d);
        }
    }

    // ---- 获取平台信息 ----
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // ---- UB 级 tiling: 计算 tileSize ----
    // inQueue: double buffer, tileSize^2 * blockSize 个元素
    // outQueue: double buffer, tileSize^2 * blockSize 个元素
    // 总计: 4 * tileSize^2 * blockSize * dtypeSize <= ubSize
    int64_t bufCoeff = 4 * blockSize * dtypeSize;
    int64_t maxTileElems = static_cast<int64_t>(ubSize) / bufCoeff;
    int64_t tileSize = static_cast<int64_t>(std::sqrt(static_cast<double>(maxTileElems)));
    if (tileSize < 1) tileSize = 1;
    if (tileSize > 64) tileSize = 64;
    // 确保每个 row 有至少 blockSize 元素
    if (tileSize * blockSize < 1) tileSize = 1;

    // ---- Block 级 tiling ----
    int64_t usedCoreNum = std::min(batchCount, coreNum);
    if (usedCoreNum < 1) usedCoreNum = 1;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // ---- 准备 launch 参数 ----
    // 需要将 vector 转为独立变量, 因为 EXEC_KERNEL_CMD 要求左值
    int64_t blockSizeL = blockSize;
    int64_t dimASizeL = dimASize;
    int64_t dimBSizeL = dimBSize;
    int64_t tileSizeL = tileSize;
    int64_t ndimL = ndim;
    int64_t batchCountL = batchCount;
    int64_t dimAL = dimA;
    int64_t dimBL = dimB;
    int64_t dimAOutL = dimAOut;
    int64_t dimBOutL = dimBOut;

    int64_t inputShapeL[4] = {1, 1, 1, 1};
    int64_t outputShapeL[4] = {1, 1, 1, 1};
    int64_t inputStridesL[4] = {0, 0, 0, 0};
    int64_t outputStridesL[4] = {0, 0, 0, 0};

    for (int64_t i = 0; i < ndim; ++i) {
        inputShapeL[i] = selfContiguous.size(i);
        outputShapeL[i] = output.size(i);
        inputStridesL[i] = inputStridesV[i];
        outputStridesL[i] = outputStridesV[i];
    }

    // ---- 单次 Launch ----
    EXEC_KERNEL_CMD(transpose_v2, blockDim,
        selfContiguous, output,
        blockSizeL,
        dimASizeL, dimBSizeL,
        tileSizeL,
        batchCountL,
        ndimL,
        dimAL, dimBL, dimAOutL, dimBOutL,
        inputShapeL[0], inputShapeL[1], inputShapeL[2], inputShapeL[3],
        outputShapeL[0], outputShapeL[1], outputShapeL[2], outputShapeL[3],
        inputStridesL[0], inputStridesL[1], inputStridesL[2], inputStridesL[3],
        outputStridesL[0], outputStridesL[1], outputStridesL[2], outputStridesL[3],
        dtypeSize
    );

    return output;
}

}  // namespace ascend_kernel
