#include "kernel_operator.h"

using namespace AscendC;

/*
 * TransposeV2 Kernel — Tiled 2D Transpose
 *
 * 识别互换二维 (dimA, dimB)，将其作为 2D 矩阵，其他维作为 batch。
 * 对每个 batch 内的矩阵做分块转置。
 *
 * blockSize: 比 dimA/dimB 更内层的维度乘积（= 内层连续元素数，作搬移粒度）
 */

template<typename T>
class TransposeV2Kernel {
public:
    __aicore__ inline TransposeV2Kernel() {}

    __aicore__ inline void Init(
        GM_ADDR self, GM_ADDR output,
        int64_t blockSize,
        int64_t dimASize, int64_t dimBSize,
        int64_t tileSize,
        int64_t batchCount,
        int64_t ndim,
        int64_t dimA, int64_t dimB,
        int64_t dimAOut, int64_t dimBOut,
        int64_t inputShape0, int64_t inputShape1, int64_t inputShape2, int64_t inputShape3,
        int64_t outputShape0, int64_t outputShape1, int64_t outputShape2, int64_t outputShape3,
        int64_t inputStride0, int64_t inputStride1, int64_t inputStride2, int64_t inputStride3,
        int64_t outputStride0, int64_t outputStride1, int64_t outputStride2, int64_t outputStride3,
        int64_t dtypeSize);

    __aicore__ inline void Process();

private:
    // 将线性 batchIdx 分解为多维坐标，计算输入/输出 GM 基偏移
    __aicore__ inline void computeBatchOffsets(
        int64_t batchIdx, int64_t &inputBase, int64_t &outputBase);

    // 对一个 batch 内的 (dimASize, dimBSize) 矩阵做分块转置
    __aicore__ inline void processTransposeTile(
        int64_t inputBase, int64_t outputBase);

    // UB 内块转置
    __aicore__ inline void transposeInUB(
        int64_t curM, int64_t curN,
        int64_t alignedCellSize);

    // 32B 整除检查
    __aicore__ inline int64_t alignTo32B(int64_t bytes, int64_t sizeofT);

private:
    TPipe pipe;
    TQue<TPosition::VECIN, 1> inQueue;
    TQue<TPosition::VECOUT, 1> outQueue;
    GlobalTensor<T> selfGm;
    GlobalTensor<T> outputGm;

    int64_t blockSize_;
    int64_t dimASize_, dimBSize_;
    int64_t tileSize_;
    int64_t batchCount_;
    int64_t ndim_;
    int64_t dimA_, dimB_;
    int64_t dimAOut_, dimBOut_;
    int64_t inputShape_[4], outputShape_[4];
    int64_t inputStrides_[4], outputStrides_[4];
    int64_t dtypeSize_;
    int64_t tileElements_;
    int64_t alignedCellSize_;  // 32B 对齐后的 cell 大小 (元素数)
    bool useDataCopyTranspose_;  // alignedCellSize * sizeof(T) >= 32
};

// =========================== Init ============================

template<typename T>
__aicore__ inline int64_t TransposeV2Kernel<T>::alignTo32B(int64_t bytes, int64_t sizeofT) {
    return ((bytes + 31) / 32) * (32 / sizeofT);
}

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::Init(
    GM_ADDR self, GM_ADDR output,
    int64_t blockSize,
    int64_t dimASize, int64_t dimBSize,
    int64_t tileSize,
    int64_t batchCount,
    int64_t ndim,
    int64_t dimA, int64_t dimB,
    int64_t dimAOut, int64_t dimBOut,
    int64_t inputShape0, int64_t inputShape1, int64_t inputShape2, int64_t inputShape3,
    int64_t outputShape0, int64_t outputShape1, int64_t outputShape2, int64_t outputShape3,
    int64_t inputStride0, int64_t inputStride1, int64_t inputStride2, int64_t inputStride3,
    int64_t outputStride0, int64_t outputStride1, int64_t outputStride2, int64_t outputStride3,
    int64_t dtypeSize) {

    blockSize_ = blockSize;
    dimASize_ = dimASize; dimBSize_ = dimBSize;
    tileSize_ = tileSize;
    batchCount_ = batchCount;
    ndim_ = ndim;
    dimA_ = dimA; dimB_ = dimB;
    dimAOut_ = dimAOut; dimBOut_ = dimBOut;
    dtypeSize_ = dtypeSize;

    inputShape_[0] = inputShape0; inputShape_[1] = inputShape1;
    inputShape_[2] = inputShape2; inputShape_[3] = inputShape3;
    outputShape_[0] = outputShape0; outputShape_[1] = outputShape1;
    outputShape_[2] = outputShape2; outputShape_[3] = outputShape3;
    inputStrides_[0] = inputStride0; inputStrides_[1] = inputStride1;
    inputStrides_[2] = inputStride2; inputStrides_[3] = inputStride3;
    outputStrides_[0] = outputStride0; outputStrides_[1] = outputStride1;
    outputStrides_[2] = outputStride2; outputStrides_[3] = outputStride3;

    int64_t inputTotal = 1, outputTotal = 1;
    for (int64_t i = 0; i < ndim_; ++i) {
        inputTotal *= inputShape_[i];
        outputTotal *= outputShape_[i];
    }
    selfGm.SetGlobalBuffer((__gm__ T*)self, inputTotal);
    outputGm.SetGlobalBuffer((__gm__ T*)output, outputTotal);

    // 32B 对齐的 cell 大小
    int64_t sizeofT = static_cast<int64_t>(sizeof(T));
    alignedCellSize_ = alignTo32B(blockSize_ * sizeofT, sizeofT);

    // UB 内转置: 若 aligned cell 满足 32B 对齐, 用 DataCopy
    useDataCopyTranspose_ = (alignedCellSize_ * sizeofT >= 32);

    // 每个 tile buffer 的大小: tileSize * tileSize * alignedCellSize_ 个元素
    // 确保 32B 对齐: tileSize * alignedCellSize_ * sizeofT 必须 32B 对齐
    tileElements_ = tileSize_ * tileSize_ * alignedCellSize_;
    int64_t bufBytes = tileElements_ * sizeofT;
    pipe.InitBuffer(inQueue, 2, bufBytes);
    pipe.InitBuffer(outQueue, 2, bufBytes);
}

// =========================== computeBatchOffsets ============================

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::computeBatchOffsets(
    int64_t batchIdx, int64_t &inputBase, int64_t &outputBase) {
    int64_t coord[4] = {0, 0, 0, 0};
    int64_t remaining = batchIdx;
    for (int64_t d = ndim_ - 1; d >= 0; --d) {
        if (d == dimA_ || d == dimB_) continue;
        int64_t dimSize = inputShape_[d];
        coord[d] = remaining % dimSize;
        remaining /= dimSize;
    }

    inputBase = 0;
    for (int64_t d = 0; d < ndim_; ++d) {
        if (d == dimA_ || d == dimB_) continue;
        inputBase += coord[d] * inputStrides_[d];
    }

    outputBase = 0;
    for (int64_t i = 0; i < ndim_; ++i) {
        if (i == dimAOut_ || i == dimBOut_) continue;
        outputBase += coord[i] * outputStrides_[i];
    }
}

// =========================== transposeInUB ============================

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::transposeInUB(
    int64_t curM, int64_t curN, int64_t alignedCellSize) {

    LocalTensor<T> inLocal = inQueue.DeQue<T>();
    LocalTensor<T> outLocal = outQueue.AllocTensor<T>();

    // inLocal 布局: row r 从 r * tileSize_ * alignedCellSize 开始
    //   cell (r, c) 在 r * tileSize_ * alignedCellSize + c * alignedCellSize
    //   每个 cell 有 blockSize_ 个有效元素, 存放在 alignedCellSize 空间内 (可能有 padding)
    // outLocal 布局: 同理对称

    int64_t rowStride = tileSize_ * alignedCellSize;

    if (useDataCopyTranspose_) {
        // alignedCellSize * sizeof(T) >= 32, 用 DataCopy
        for (int64_t r = 0; r < curM; ++r) {
            for (int64_t c = 0; c < curN; ++c) {
                DataCopy(
                    outLocal[c * rowStride + r * alignedCellSize],
                    inLocal[r * rowStride + c * alignedCellSize],
                    static_cast<uint32_t>(blockSize_));
            }
        }
    } else {
        // 小 cell 用 SetValue/GetValue
        for (int64_t r = 0; r < curM; ++r) {
            for (int64_t c = 0; c < curN; ++c) {
                int64_t inOff = r * rowStride + c * alignedCellSize;
                int64_t outOff = c * rowStride + r * alignedCellSize;
                for (int64_t b = 0; b < blockSize_; ++b) {
                    outLocal.SetValue(outOff + b, inLocal.GetValue(inOff + b));
                }
            }
        }
    }

    inQueue.FreeTensor(inLocal);
    outQueue.EnQue(outLocal);
}

// =========================== processTransposeTile ============================

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::processTransposeTile(
    int64_t inputBase, int64_t outputBase) {

    int64_t sizeofT = static_cast<int64_t>(sizeof(T));
    int64_t tileSize = tileSize_;
    int64_t blockSize = blockSize_;
    int64_t alignedCellSize = alignedCellSize_;
    int64_t rowStride = tileSize * alignedCellSize;
    int64_t dimASize = dimASize_;
    int64_t dimBSize = dimBSize_;

    int64_t dimATiles = (dimASize + tileSize - 1) / tileSize;
    int64_t dimBTiles = (dimBSize + tileSize - 1) / tileSize;

    for (int64_t ta = 0; ta < dimATiles; ++ta) {
        int64_t curM = tileSize;
        if (ta == dimATiles - 1) curM = dimASize - ta * tileSize;

        for (int64_t tb = 0; tb < dimBTiles; ++tb) {
            int64_t curN = tileSize;
            if (tb == dimBTiles - 1) curN = dimBSize - tb * tileSize;

            // === CopyIn ===
            // 读入 curM 行，每行 curN 个 cell，每个 cell blockSize 个元素
            // 在 input GM 中，同一行内的 cell 是连续的 (inputStrides[dimB] == blockSize)
            // 行间 stride = inputStrides[dimA_]
            {
                LocalTensor<T> inLocal = inQueue.AllocTensor<T>();
                int64_t rowBytes = curN * blockSize * sizeofT;
                int64_t srcStrideBytes = inputStrides_[dimA_] * sizeofT;
                int64_t tileInputBase = inputBase
                    + ta * tileSize * inputStrides_[dimA_]
                    + tb * tileSize * inputStrides_[dimB_];

                int64_t dstStrideDB = (rowStride * sizeofT) / 32;

                DataCopyExtParams copyInParams{
                    static_cast<uint16_t>(curM),
                    static_cast<uint32_t>(rowBytes),
                    static_cast<uint32_t>(srcStrideBytes),
                    static_cast<uint16_t>(dstStrideDB > 0 ? dstStrideDB : 1),
                    0
                };
                DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
                DataCopyPad(inLocal, selfGm[tileInputBase], copyInParams, padParams);
                inQueue.EnQue(inLocal);
            }

            // === Compute (UB 内转置) ===
            transposeInUB(curM, curN, alignedCellSize);

            // === CopyOut ===
            // 写出转置后的 curN 行，每行 curM 个 cell
            // 在 output GM 中，同一行内的 cell 之间有 stride 间隔
            // 输出 tile 起始位置: dimA 值→dimBOut_, dimB 值→dimAOut_
            {
                LocalTensor<T> outLocal = outQueue.DeQue<T>();
                int64_t tileOutputBase = outputBase
                    + ta * tileSize * outputStrides_[dimBOut_]
                    + tb * tileSize * outputStrides_[dimAOut_];

                // 逐行写出: 每行 curM 个 cell，cell 间 stride = dimBOutputStride
                for (int64_t c = 0; c < curN; ++c) {
                    int64_t rowGmBase = tileOutputBase
                        + static_cast<int64_t>(c) * outputStrides_[dimAOut_];

                    // cell 间 gap: dimBOutputStride - blockSize 个元素
                    int64_t dstStrideElems = outputStrides_[dimBOut_];
                    int64_t dstStrideBytes = dstStrideElems * sizeofT;

                    // UB 中 row c 的第一 cell 偏移
                    int64_t outRowUbOff = c * rowStride;

                    DataCopyExtParams copyOutParams{
                        static_cast<uint16_t>(curM),                 // curM cells
                        static_cast<uint32_t>(blockSize * sizeofT),  // bytes per cell
                        static_cast<uint16_t>(0),                    // packed in UB (cells side-by-side)
                        static_cast<uint32_t>(dstStrideBytes),       // stride between cells in GM
                        0
                    };
                    DataCopyPad(outputGm[rowGmBase], outLocal[outRowUbOff], copyOutParams);
                }
                outQueue.FreeTensor(outLocal);
            }
        }
    }
}

// =========================== Process ============================

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::Process() {
    int64_t blockIdx = static_cast<int64_t>(GetBlockIdx());
    int64_t blockDim = static_cast<int64_t>(GetBlockNum());
    if (blockDim < 1) blockDim = 1;

    int64_t totalBatches = batchCount_;
    int64_t batchesPerCore = totalBatches / blockDim;
    int64_t remainder = totalBatches % blockDim;

    int64_t myStart, myNum;
    if (blockIdx < remainder) {
        myStart = blockIdx * (batchesPerCore + 1);
        myNum = batchesPerCore + 1;
    } else {
        myStart = remainder * (batchesPerCore + 1)
            + (blockIdx - remainder) * batchesPerCore;
        myNum = batchesPerCore;
    }
    if (myNum <= 0) return;

    for (int64_t bi = 0; bi < myNum; ++bi) {
        int64_t batchIdx = myStart + bi;
        int64_t inputBase = 0, outputBase = 0;
        computeBatchOffsets(batchIdx, inputBase, outputBase);
        processTransposeTile(inputBase, outputBase);
    }
}

// =========================== Kernel 入口 ============================

extern "C" __global__ __aicore__ void transpose_v2(
    GM_ADDR self, GM_ADDR output,
    int64_t blockSize,
    int64_t dimASize, int64_t dimBSize,
    int64_t tileSize,
