        op.Process();
    } else if (dtypeSize == 2) {
        TransposeV2Kernel<half> op;
        op.Init(self, output, blockSize, dimASize, dimBSize, tileSize,
                batchCount, ndim, dimA, dimB, dimAOut, dimBOut,
