#include "kernel_operator.h"

using namespace AscendC;

/*
 * TransposeV2 Kernel — 简化版（直通测试）
 * 先验证 CopyIn→CopyOut 直通正确，再恢复 transpose 逻辑。
 */

template<typename T>
class TransposeV2Kernel {
public:
    __aicore__ inline TransposeV2Kernel() {}

    __aicore__ inline void Init(
        GM_ADDR self, GM_ADDR output,
        int64_t blockSize,
        int64_t dimASize, int64_t dimBSize,
        int64_t tileSize,
        int64_t batchCount,
        int64_t ndim,
        int64_t dimA, int64_t dimB,
        int64_t dimAOut, int64_t dimBOut,
        int64_t inputShape0, int64_t inputShape1, int64_t inputShape2, int64_t inputShape3,
        int64_t outputShape0, int64_t outputShape1, int64_t outputShape2, int64_t outputShape3,
        int64_t inputStride0, int64_t inputStride1, int64_t inputStride2, int64_t inputStride3,
        int64_t outputStride0, int64_t outputStride1, int64_t outputStride2, int64_t outputStride3,
        int64_t dtypeSize);

    __aicore__ inline void Process();

private:
    TPipe pipe;
    TQue<TPosition::VECIN, 1> inQueue;
    TQue<TPosition::VECOUT, 1> outQueue;
    GlobalTensor<T> selfGm;
    GlobalTensor<T> outputGm;

    int64_t totalElems_;
    int64_t formerNum_, formerLength_, tailNum_, tailLength_;
    int64_t tileLength_;
};

// =========================== Init ============================

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::Init(
    GM_ADDR self, GM_ADDR output,
    int64_t /*blockSize*/,
    int64_t /*dimASize*/, int64_t /*dimBSize*/,
    int64_t /*tileSize*/,
    int64_t /*batchCount*/,
    int64_t ndim,
    int64_t /*dimA*/, int64_t /*dimB*/,
    int64_t /*dimAOut*/, int64_t /*dimBOut*/,
    int64_t inputShape0, int64_t inputShape1, int64_t inputShape2, int64_t inputShape3,
    int64_t outputShape0, int64_t outputShape1, int64_t outputShape2, int64_t outputShape3,
    int64_t /*inputStride0*/, int64_t /*inputStride1*/, int64_t /*inputStride2*/, int64_t /*inputStride3*/,
    int64_t /*outputStride0*/, int64_t /*outputStride1*/, int64_t /*outputStride2*/, int64_t /*outputStride3*/,
    int64_t dtypeSize) {

    // 简化为线性拷贝: 读入 totalElems 个元素, 写出 totalElems 元素
    int64_t inputShape[4] = {inputShape0, inputShape1, inputShape2, inputShape3};
    int64_t outputShape[4] = {outputShape0, outputShape1, outputShape2, outputShape3};
    totalElems_ = 1;
    for (int64_t i = 0; i < ndim; ++i) {
        totalElems_ *= outputShape[i];
    }
    selfGm.SetGlobalBuffer((__gm__ T*)self, totalElems_);
    outputGm.SetGlobalBuffer((__gm__ T*)output, totalElems_);

    // 简化的 block tiling: 按总元素数切分
    int64_t coreNum = 40;  // 保守估计
    int64_t sizeofT = dtypeSize;
    int64_t cacheLineElems = 512 / sizeofT;

    int64_t perCore = (totalElems_ + coreNum - 1) / coreNum;
    int64_t perCoreAlign = ((perCore + cacheLineElems - 1) / cacheLineElems) * cacheLineElems;
    if (perCoreAlign < cacheLineElems) perCoreAlign = cacheLineElems;
    int64_t usedCoreNum = (totalElems_ + perCoreAlign - 1) / perCoreAlign;
    if (usedCoreNum < 1) usedCoreNum = 1;

    formerNum_ = usedCoreNum - 1;
    if (formerNum_ < 0) formerNum_ = 0;
    formerLength_ = perCoreAlign;
    tailNum_ = (usedCoreNum > 0 && totalElems_ > formerNum_ * formerLength_) ? 1 : 0;
    tailLength_ = totalElems_ - formerNum_ * formerLength_;
    if (tailLength_ < 0) tailLength_ = 0;

    // UB tiling: 简单的连续拷贝
    int64_t ubSize = 192 * 1024;
    int64_t maxElemPerTile = ubSize / (4 * sizeofT);
    tileLength_ = (maxElemPerTile / cacheLineElems) * cacheLineElems;
    if (tileLength_ < cacheLineElems) tileLength_ = cacheLineElems;
    if (tileLength_ > totalElems_) tileLength_ = totalElems_;

    pipe.InitBuffer(inQueue, 2, tileLength_ * sizeofT);
    pipe.InitBuffer(outQueue, 2, tileLength_ * sizeofT);
}

template<typename T>
__aicore__ inline void TransposeV2Kernel<T>::Process() {
    int64_t blockIdx = static_cast<int64_t>(GetBlockIdx());
    int64_t blockLen = (blockIdx < formerNum_) ? formerLength_ : tailLength_;
    if (blockLen <= 0) return;
    int64_t blockStart = blockIdx * formerLength_;

    int64_t tileNum = (blockLen + tileLength_ - 1) / tileLength_;

    for (int64_t t = 0; t < tileNum; ++t) {
        int64_t curLen = tileLength_;
        if (t == tileNum - 1) curLen = blockLen - t * tileLength_;
        int64_t offset = blockStart + t * tileLength_;

        // CopyIn
        {
            LocalTensor<T> inLocal = inQueue.AllocTensor<T>();
            DataCopyExtParams p{1, static_cast<uint32_t>(curLen * static_cast<int64_t>(sizeof(T))), 0, 0, 0};
            DataCopyPadExtParams<T> pad{false, 0, 0, 0};
            DataCopyPad(inLocal, selfGm[offset], p, pad);
            inQueue.EnQue(inLocal);
        }

        // Compute (直通: 不做转置)
        {
            LocalTensor<T> inLocal = inQueue.DeQue<T>();
            LocalTensor<T> outLocal = outQueue.AllocTensor<T>();
            for (int64_t i = 0; i < curLen; ++i) {
                outLocal.SetValue(i, inLocal.GetValue(i));
            }
            inQueue.FreeTensor(inLocal);
            outQueue.EnQue(outLocal);
        }

        // CopyOut
        {
            LocalTensor<T> outLocal = outQueue.DeQue<T>();
            DataCopyExtParams p{1, static_cast<uint32_t>(curLen * static_cast<int64_t>(sizeof(T))), 0, 0, 0};
            DataCopyPad(outputGm[offset], outLocal, p);
            outQueue.FreeTensor(outLocal);
        }
    }
}

